import{_ as u,a0 as i,w as s,s as p,ao as o,I as n,x as r,a1 as e,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"Greg Kroah-Hartman 解釋內核社區是如何使 Linux 安全的 | LCTT x X-CMD","titleTemplate":false,"description":"Greg Kroah-Hartman 解釋內核社區是如何使 Linux 安全的 | LCTT (201811) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Greg Kroah-Hartman 解釋內核社區是如何使 Linux 安全的 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Greg Kroah-Hartman 解釋內核社區是如何使 Linux 安全的 | LCTT (201811) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201811/20181002 Greg Kroah-Hartman Explains How the Kernel Community Is Securing Linux","title":"Greg Kroah-Hartman 解釋內核社區是如何使 Linux 安全的","tag":"201811","desc":""},"relativePath":"201811/20181002 Greg Kroah-Hartman Explains How the Kernel Community Is Securing Linux.md","filePath":"[post].md"}'),m={name:"201811/20181002 Greg Kroah-Hartman Explains How the Kernel Community Is Securing Linux.md"};function g(d,t,x,w,f,b){const a=i("Link");return s(),p("div",null,[t[21]||(t[21]=o('<h1 id="greg-kroah-hartman-解釋內核社區是如何使-linux-安全的" tabindex="-1">Greg Kroah-Hartman 解釋內核社區是如何使 Linux 安全的 <a class="header-anchor" href="#greg-kroah-hartman-解釋內核社區是如何使-linux-安全的" aria-label="Permalink to “Greg Kroah-Hartman 解釋內核社區是如何使 Linux 安全的”">​</a></h1><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/kernel-security_0.jpg?itok=hOaTQwWV" alt=""></p><blockquote><p>內核維護者 Greg Kroah-Hartman 談論內核社區如何保護 Linux 不遭受損害。</p></blockquote><p>由於 Linux 使用量持續擴大，內核社區去提高這個世界上使用最廣泛的技術 —— Linux 內核的安全性的重要性越來越高。安全不僅對企業客户很重要，它對消費者也很重要，因為 80% 的移動設備都使用了 Linux。在本文中，Linux 內核維護者 Greg Kroah-Hartman 帶我們瞭解內核社區如何應對威脅。</p><h3 id="bug-不可避免" tabindex="-1">bug 不可避免 <a class="header-anchor" href="#bug-不可避免" aria-label="Permalink to “bug 不可避免”">​</a></h3><p><img src="https://www.linux.com/sites/lcom/files/styles/floated_images/public/greg-k-h.png?itok=p4fREYuj" alt="Greg Kroah-Hartman" title="Greg Kroah-Hartman"></p>',6)),n("p",null,[n("em",null,[t[1]||(t[1]=r("Greg Kroah-Hartman ",-1)),e(a,{href:"https://www.linux.com/licenses/category/linux-foundation"},{default:l(()=>[...t[0]||(t[0]=[r("Linux 基金會",-1)])]),_:1})])]),t[22]||(t[22]=n("p",null,"正如 Linus Torvalds 曾經説過的，大多數安全問題都是 bug 造成的，而 bug 又是軟件開發過程的一部分。是軟件就有 bug。",-1)),t[23]||(t[23]=n("p",null,"Kroah-Hartman 説：“就算是 bug，我們也不知道它是安全的 bug 還是不安全的 bug。我修復的一個著名 bug，在三年後才被 Red Hat 認定為安全漏洞“。",-1)),t[24]||(t[24]=n("p",null,"在消除 bug 方面，內核社區沒有太多的辦法，只能做更多的測試來尋找 bug。內核社區現在已經有了自己的安全團隊，它們是由熟悉內核核心的內核開發者組成。",-1)),t[25]||(t[25]=n("p",null,"Kroah-Hartman 説：”當我們收到一個報告時，我們就讓參與這個領域的核心開發者去修復它。在一些情況下，他們可能是同一個人，讓他們進入安全團隊可以更快地解決問題“。但他也強調，內核所有部分的開發者都必須清楚地瞭解這些問題，因為內核是一個可信環境，它必須被保護起來。",-1)),t[26]||(t[26]=n("p",null,"Kroah-Hartman 説：”一旦我們修復了它，我們就將它放到我們的棧分析規則中，以便於以後不再重新出現這個 bug。“",-1)),t[27]||(t[27]=n("p",null,"除修復 bug 之外，內核社區也不斷加固內核。Kroah-Hartman 説：“我們意識到，我們需要一些主動的緩減措施，因此我們需要加固內核。”",-1)),t[28]||(t[28]=n("p",null,"Kees Cook 和其他一些人付出了巨大的努力，帶來了一直在內核之外的加固特性，並將它們合併或適配到內核中。在每個內核發行後，Cook 都對所有新的加固特性做一個總結。但是隻加固內核是不夠的，供應商們必須要啓用這些新特性來讓它們充分發揮作用，但他們並沒有這麼做。",-1)),n("p",null,[t[3]||(t[3]=r("Kroah-Hartman ",-1)),e(a,{href:"https://www.kernel.org/category/releases.html"},{default:l(()=>[...t[2]||(t[2]=[r("每週發佈一個穩定版內核",-1)])]),_:1}),t[4]||(t[4]=r("，而為了長期的支持，公司們只從中挑選一個，以便於設備製造商能夠利用它。但是，Kroah-Hartman 注意到，除了 Google Pixel 之外，大多數 Android 手機並不包含這些額外的安全加固特性，這就意味着，所有的這些手機都是有漏洞的。他説：“人們應該去啓用這些加固特性”。",-1))]),t[29]||(t[29]=o('<p>Kroah-Hartman 説：“我購買了基於 Linux 內核 4.4 的所有旗艦級手機，去查看它們中哪些確實升級了新特性。結果我發現只有一家公司升級了它們的內核。……我在整個供應鏈中努力去解決這個問題，因為這是一個很棘手的問題。它涉及許多不同的組織 —— SoC 製造商、運營商等等。關鍵點是，需要他們把我們辛辛苦苦設計的內核去推送給大家。”</p><p>好消息是，與消費電子產品不一樣，像 Red Hat 和 SUSE 這樣的大供應商，在企業環境中持續對內核進行更新。使用容器、pod 和虛擬化的現代系統做到這一點更容易了。無需停機就可以毫不費力地更新和重啓。事實上，現在來保證系統安全相比過去容易多了。</p><h3 id="meltdown-和-spectre" tabindex="-1">Meltdown 和 Spectre <a class="header-anchor" href="#meltdown-和-spectre" aria-label="Permalink to “Meltdown 和 Spectre”">​</a></h3><p>沒有任何一個關於安全的討論能夠避免提及 Meltdown 和 Spectre 缺陷。內核社區一直致力於修改新發現的和已查明的安全漏洞。不管怎樣，Intel 已經因為這些事情改變了它們的策略。</p><p>Kroah-Hartman 説：“他們已經重新研究如何處理安全 bug，以及如何與社區合作，因為他們知道他們做錯了。內核已經修復了幾乎所有大的 Spectre 問題，但是還有一些小問題仍在處理中”。</p><p>好消息是，這些 Intel 漏洞使得內核社區正在變得更好。Kroah-Hartman 説：“我們需要做更多的測試。對於最新一輪的安全補丁，在它們被髮布之前，我們自己花了四個月時間來測試它們，因為我們要防止這個安全問題在全世界擴散。而一旦這些漏洞在真實的世界中被利用，將讓我們認識到我們所依賴的基礎設施是多麼的脆弱，我們多年來一直在做這種測試，這確保了其它人不會遭到這些 bug 的傷害。所以説，Intel 的這些漏洞在某種程度上讓內核社區變得更好了”。</p><p>對安全的日漸關注也為那些有才華的人創造了更多的工作機會。由於安全是個極具吸引力的領域，那些希望在內核空間中有所建樹的人，安全將是他們一個很好的起點。</p><p>Kroah-Hartman 説：“如果有人想從事這方面的工作，我們有大量的公司願意僱傭他們。我知道一些開始去修復 bug 的人已經被他們僱傭了。”</p><p>你可以在下面鏈接的視頻上查看更多的內容：</p>',9)),n("p",null,[e(a,{href:"https://youtu.be/jkGVabyMh1I"},{default:l(()=>[...t[5]||(t[5]=[r("視頻",-1)])]),_:1})]),t[30]||(t[30]=n("hr",null,null,-1)),n("p",null,[t[7]||(t[7]=r("via: ",-1)),e(a,{href:"https://www.linux.com/blog/2018/10/greg-kroah-hartman-explains-how-kernel-community-securing-linux-0"},{default:l(()=>[...t[6]||(t[6]=[r("https://www.linux.com/blog/2018/10/greg-kroah-hartman-explains-how-kernel-community-securing-linux-0",-1)])]),_:1})]),n("p",null,[t[12]||(t[12]=r("作者：",-1)),e(a,{href:"https://www.linux.com/users/arnieswap"},{default:l(()=>[...t[8]||(t[8]=[r("SWAPNIL BHARTIYA",-1)])]),_:1}),t[13]||(t[13]=r(" 選題：",-1)),e(a,{href:"https://github.com/oska874"},{default:l(()=>[...t[9]||(t[9]=[r("oska874",-1)])]),_:1}),t[14]||(t[14]=r(" 譯者：",-1)),e(a,{href:"https://github.com/qhwdw"},{default:l(()=>[...t[10]||(t[10]=[r("qhwdw",-1)])]),_:1}),t[15]||(t[15]=r(" 校對：",-1)),e(a,{href:"https://github.com/wxy"},{default:l(()=>[...t[11]||(t[11]=[r("wxy",-1)])]),_:1})]),n("p",null,[t[18]||(t[18]=r("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[16]||(t[16]=[r("LCTT",-1)])]),_:1}),t[19]||(t[19]=r(" 原創編譯，",-1)),e(a,{href:"https://linux.cn/"},{default:l(()=>[...t[17]||(t[17]=[r("Linux中國",-1)])]),_:1}),t[20]||(t[20]=r(" 榮譽推出",-1))])])}const K=u(m,[["render",g]]);export{T as __pageData,K as default};
